// Transport-only offline entry point for the pinned upstream FAST-LIO2 core.
// Estimator callbacks are generated byte-for-byte from licensed laserMapping.cpp.
#include <cstdint>
#include <stdexcept>
#include <iomanip>

template<class T> T read_value(std::istream& in) {
    T value;
    if (!in.read(reinterpret_cast<char*>(&value), sizeof(value))) throw std::runtime_error("truncated native transport");
    return value;
}

int main(int argc, char** argv) {
    if (argc != 3) throw std::runtime_error("usage: fastlio_headless input.bin output.jsonl");
    std::ifstream input(argv[1], std::ios::binary);
    std::ofstream output(argv[2]);
    if (!input || !output) throw std::runtime_error("cannot open native transport/output");
    char magic[8]; input.read(magic, 8);
    if (std::string(magic, 8) != "BHLFAST1") throw std::runtime_error("wrong native transport");
    for (int row=0; row<3; ++row) for (int col=0; col<3; ++col) Lidar_R_wrt_IMU(row,col)=read_value<double>(input);
    for (int i=0; i<3; ++i) Lidar_T_wrt_IMU(i)=read_value<double>(input);
    filter_size_surf_min=read_value<double>(input);
    filter_size_map_min=read_value<double>(input);
    const double blind=read_value<double>(input);
    const auto filter_every=read_value<uint32_t>(input);
    const auto count=read_value<uint32_t>(input);
    if (!(filter_size_surf_min>0 && filter_size_map_min>0 && blind>=0 && filter_every>0 && count>0)) throw std::runtime_error("invalid native config");
    cube_len=200; DET_RANGE=20; extrinsic_est_en=false; NUM_MAX_ITERATIONS=4; lidar_type=VELO16;
    memset(point_selected_surf, true, sizeof(point_selected_surf));
    downSizeFilterSurf.setLeafSize(filter_size_surf_min, filter_size_surf_min, filter_size_surf_min);
    p_imu->set_extrinsic(Lidar_T_wrt_IMU, Lidar_R_wrt_IMU);
    p_imu->set_gyr_cov(V3D(.1,.1,.1)); p_imu->set_acc_cov(V3D(.1,.1,.1));
    p_imu->set_gyr_bias_cov(V3D(.0001,.0001,.0001)); p_imu->set_acc_bias_cov(V3D(.0001,.0001,.0001));
    p_imu->lidar_type=VELO16;
    double epsi[23]; std::fill(epsi,epsi+23,.001);
    kf.init_dyn_share(get_f,df_dx,df_dw,h_share_model,NUM_MAX_ITERATIONS,epsi);
    output << std::setprecision(17);
    for (uint32_t index=0; index<count; ++index) {
        Measures.lidar_beg_time=read_value<double>(input);
        Measures.lidar_end_time=read_value<double>(input);
        const auto points=read_value<uint32_t>(input), imus=read_value<uint32_t>(input);
        if (points>100000 || imus>10000) throw std::runtime_error("transport scan exceeds upstream buffers");
        Measures.lidar.reset(new PointCloudXYZI()); Measures.imu.clear();
        for (uint32_t i=0; i<points; ++i) {
            PointType p{}; p.x=read_value<float>(input);p.y=read_value<float>(input);p.z=read_value<float>(input);
            p.intensity=read_value<float>(input);const auto time=read_value<float>(input); const auto ring=read_value<uint16_t>(input);
            (void)ring;
            // Equivalent to native given-offset, feature-disabled Velodyne preprocessing.
            p.curvature=time*1000.0f;
            if (i%filter_every==0 && p.x*p.x+p.y*p.y+p.z*p.z>blind*blind) Measures.lidar->push_back(p);
        }
        for (uint32_t i=0; i<imus; ++i) {
            sensor_msgs::Imu::Ptr imu(new sensor_msgs::Imu());
            imu->header.stamp.fromSec(read_value<double>(input));
            imu->angular_velocity.x=read_value<double>(input);imu->angular_velocity.y=read_value<double>(input);imu->angular_velocity.z=read_value<double>(input);
            imu->linear_acceleration.x=read_value<double>(input);imu->linear_acceleration.y=read_value<double>(input);imu->linear_acceleration.z=read_value<double>(input);
            Measures.imu.push_back(imu);
        }
        const double started=omp_get_wtime();
        bool tracked=false; std::string status="INITIALIZING";
        effct_feat_num=0;
        if (index==0) {
            first_lidar_time=Measures.lidar_beg_time;p_imu->first_lidar_time=first_lidar_time;
            status="UPSTREAM_FIRST_SCAN";
        } else if (Measures.imu.empty()) {
            status="MISSING_IMU";
        } else {
            match_time=0;kdtree_search_time=0;solve_time=0;
            feats_undistort->clear();
            p_imu->Process(Measures,kf,feats_undistort);
            state_point=kf.get_x();pos_lid=state_point.pos+state_point.rot*state_point.offset_T_L_I;
            if (feats_undistort->empty()) status="IMU_INITIALIZING";
            else {
                flg_EKF_inited=(Measures.lidar_beg_time-first_lidar_time)>=INIT_TIME;
                lasermap_fov_segment();downSizeFilterSurf.setInputCloud(feats_undistort);downSizeFilterSurf.filter(*feats_down_body);
                feats_down_size=feats_down_body->size();
                if (ikdtree.Root_Node==nullptr) {
                    if (feats_down_size>5) {
                        ikdtree.set_downsample_param(filter_size_map_min);feats_down_world->resize(feats_down_size);
                        for(int i=0;i<feats_down_size;++i) pointBodyToWorld(&feats_down_body->points[i],&feats_down_world->points[i]);
                        ikdtree.Build(feats_down_world->points);
                    }
                    status="MAP_INITIALIZING";
                } else if (feats_down_size<5) status="INSUFFICIENT_SCAN_POINTS";
                else {
                    normvec->resize(feats_down_size);feats_down_world->resize(feats_down_size);
                    pointSearchInd_surf.resize(feats_down_size);Nearest_Points.resize(feats_down_size);
                    double solve_H_time=0;kf.update_iterated_dyn_share_modified(LASER_POINT_COV,solve_H_time);
                    state_point=kf.get_x();pos_lid=state_point.pos+state_point.rot*state_point.offset_T_L_I;
                    tracked=effct_feat_num>0 && state_point.pos.allFinite() && state_point.rot.toRotationMatrix().allFinite();
                    status=tracked?"TRACKED":"NO_EFFECTIVE_MAP_MATCHES";
                    // Upstream adds scan points even when the EKF measurement is invalid.
                    map_incremental();
                }
            }
        }
        output << "{\"frame_index\":" << index << ",\"timestamp_s\":" << Measures.lidar_end_time
               << ",\"scan_begin_s\":" << Measures.lidar_beg_time << ",\"tracked\":" << (tracked?"true":"false")
               << ",\"state\":\"" << status << "\",\"compute_seconds\":" << (omp_get_wtime()-started)
               << ",\"map_reset_id\":0,\"effective_points\":" << effct_feat_num << ",\"T_W_I\":";
        if (!tracked) output << "null";
        else {
            const M3D rotation=state_point.rot.toRotationMatrix();output << '[';
            for(int r=0;r<4;++r) {
                if(r) output << ',';output << '[';
                for(int c=0;c<4;++c) {
                    if(c) output << ',';
                    output << (r==3?(c==3?1.0:0.0):(c==3?state_point.pos[r]:rotation(r,c)));
                }output << ']';
            }output << ']';
        }
        output << "}\n";
        if (!output) throw std::runtime_error("native output write failure");
    }
    if (input.peek()!=std::char_traits<char>::eof()) throw std::runtime_error("trailing transport bytes");
    return 0;
}
